"""Build static catalog pages from verified Play evidence and editorial copy."""
from pathlib import Path
import json, html, re, textwrap, base64
import cairosvg
ROOT=Path(__file__).resolve().parents[1]
BASE='https://tripperdeelabs.com'
E=lambda s:html.escape(str(s),quote=True)
# Plain-language summaries, checked against the saved Play listing descriptions.
COPY={
'parked':('Find My Car Parking Widget for Android','Save your parking location from an Android home-screen widget. Parked uses your phone’s GPS to remember the spot without an internet connection.','Open walking directions when you return, or share, replace or clear your saved pin. Directions open in your maps app and may require internet. GPS accuracy varies, especially inside garages.',['One-tap parking reminder','Saved time and location accuracy','Share, replace and clear controls']),
'local-lore':('Local History and Landmarks Near Me for Android','Local Lore helps you explore the stories behind nearby places. Browse history, landmarks, nature notes and local legends on a map or in a list.','Search another neighborhood before a trip and follow the linked sources to learn more. Internet access is needed to retrieve content and maps.',['Map and list browsing','Theme filters','Place search and linked sources']),
'roboball':('Offline Arcade Basketball Game for Android','RoboBall is a basketball arcade game about timing your release and aiming at the hoop. Moving baskets, obstacles and changing gravity affect each shot.','Practice your timing, earn stars and collect local trophies. Offline play keeps scores and progression on your device, with no account required.',['Power-meter shooting','Practice and guided practice','Moving hoops and varied courts','Local scores, stars and trophies']),
'boss-button':('Screen Privacy Cover for Android','Boss Button places a movable button over your Android screen. Double-tap it to show a labeled privacy cover, then triple-tap the cover to return.','Choose a built-in cover or an image on your device. It works offline and requires Display over other apps access. It provides a visual cover, not a device lock; your app stays open underneath.',['Adjustable floating button','Local custom cover images','Optional authenticated dismissal','Portrait and landscape support']),
'mock-location':('Mock Location GPS Simulator for Android','Mock Location supplies test positions through Android’s Developer Options. Choose a point on a map, enter coordinates or recall a saved bookmark for authorized app testing.','Use a fixed position or a movement preset. Map resources and address search require internet. Other apps can detect or reject mock locations; this utility does not bypass those checks.',['Coordinate and address entry','Five local bookmarks','Walking, running, cycling and driving presets','Pause, resume and stop controls']),
'private-eyes':('Offline Encrypted Photo Vault for Android','Private Eyes stores selected photos and files in an encrypted vault on your Android phone. Its camera can capture photos and short silent videos directly into the vault.','The app works offline and has no internet permission. Imported originals remain outside the vault until you manage them separately. There is no recovery service or cloud backup, so a lost pattern or device can mean permanent loss.',['AES-256-GCM file encryption','Private camera and file imports','Search and media filters','Automatic locking and export controls']),
'canopy-quest':('Offline Jungle Platformer for Android','Canopy Quest is a retro jungle platformer with 90 connected rooms and 45 relics to find. Swing on vines, climb through passages and time your whip strikes.','Plan your route with the field map and return to camps as you explore. Offline play stores progress locally; clearing app storage or uninstalling removes local saves.',['Three jungle regions','Field map and in-game guide','Camp retry points and autosave','Touch, keyboard and controller controls']),
'captain-quack':('Offline Arcade Space Shooter for Android','Captain Quack sends a duck through alien formations, asteroids and gravity wells. Use the touch joystick and fire button to steer through increasingly difficult runs.','Pick up shields and weapon upgrades, then try to improve your local score. Offline play saves the top five scores and career ranks on your device.',['Touch joystick and fire button','Shield and weapon pickups','Formation-clearing bonuses','Local scores and career ranks']),
'moto-thrash':('Offline Retro Motocross Game for Android','Moto Thrash is a pixel-art motocross game with 24 tracks across four cups. Race computer opponents, balance your bike in the air and time your boost while watching engine heat.','Build courses in six local save slots or attempt bus jumps in Stunt Show. Offline play is single-player, with progress and custom courses saved on your device.',['24 tracks and four cups','Bike balance and boost controls','Course editor with six local slots','Stunt Show bus jumps']),
'salmon-tracker':('Alaska Salmon Fish Counts for Android','Salmon Tracker displays public salmon passage counts for Kenai Peninsula rivers. Compare daily counts and season totals for the runs you choose to follow.','An internet connection is needed for fresh counts and alerts. Previously downloaded reports remain cached when your connection drops. This is an unofficial client, and passage counts are not a catch forecast.',['Kenai, Kasilof and Russian River projects','Daily and cumulative charts','Prior-season comparisons','Optional count notifications']),
'dive-watch':('Dive Watch Face for Wear OS','Dive Watch pairs an analog dial with luminous markers, a date window and a battery indicator inside the left marker. Choose Classic steel, Red night or Green lume.','Customize the hands, dial finish and supported complication. Requires Wear OS 5 or newer. This is a decorative watch face: it does not add water resistance or provide dive-computer functions.',['Three included themes','Battery gauge in the dial','Customizable complication','Always-on display']),
'amelia-navigator':('Aviation Pilot Watch Face for Wear OS','Amelia Navigator combines a navy aviation-style dial, brass details and digital time. A twin-engine aircraft approaches at the top of the hour; tap to replay the animation.','Wear OS supplies available battery, steps, heart-rate and weather readings. Requires Wear OS 5 or newer. The compass-style ring is decorative, not a navigation instrument.',['12- and 24-hour digital time','Hourly aircraft animation','Two dial styles and ring accents','Minimal ambient display']),
'summit-line':('Mountain Digital Watch Face for Wear OS','Summit Line places digital time over mountain scenery. Choose a landscape, accent color and optional step-goal ring, or use scenery that changes with fixed local-time periods.','It displays data from your watch and compatible providers; it does not record hikes or provide GPS navigation. Wear OS 5 or newer is required. Personal-photo customization needs Wear OS 6 and a supported system flow.',['Five scenery options','Selectable step goals','Optional moon phase and seconds','Customizable data complications']),
'kenai-fishing-report':('Kenai Fishing Report Watch Face for Wear OS','Kenai Fishing Report shows time alongside salmon counts, river temperature and tide information on a compatible Wear OS watch. Install the separate Kenai Report Data app on the same watch for these readings.','Internet access is needed for updates. Requires Wear OS 5 or newer. The apps are independent of government agencies; reports can be delayed and do not determine whether fishing is permitted.',['Daily sockeye count and season total','Soldotna water temperature','Cape Kasilof tide predictions','Custom backgrounds and ambient display']),
'kenai-report-data':('Kenai Fish Count and Tide Complications for Wear OS','Kenai Report Data supplies public fishing-report data to compatible Wear OS complications. It is a separate watch app, not a watch face, and can work with Kenai Fishing Report or another compatible face.','It fetches ADF&G counts, USGS readings and NOAA tide predictions over the internet and caches validated reports. Requires Wear OS 5 or newer. Check official rules and conditions; this independent app does not decide whether fishing is permitted.',['Kenai late-run sockeye counts','Soldotna water readings','Cape Kasilof tide predictions','Report times, refresh and official source links']),
'launch-vector':('Rocket Launch Countdown Watch Face for Wear OS','Launch Vector displays the next rocket launch countdown with time, weather and watch data. It includes launch status, an animated rocket and an ambient display.','Install the Launch Vector Data Provider companion to refresh launch schedules. Schedule updates require internet. This is an independent design, not affiliated with or endorsed by SpaceX.',['Launch countdown and status','12- and 24-hour time','Rocket flight animation','Wear OS weather and health complications'])}
apps=json.loads((ROOT/'data/apps.json').read_text())
HEADER='<header class="site-header"><nav class="nav wrap" aria-label="Main navigation"><a class="brand" href="/">TripperDeeLabs</a><div class="links"><a href="/#apps">Apps</a><a href="/garmin/">Wear OS</a><a href="/#about">About</a></div></nav></header>'
FOOTER='<footer class="wrap"><p>TripperDeeLabs · <a href="/privacy/">Website privacy</a> · <a href="/feedback/">Feedback</a></p><p>Google Play and the Google Play logo are trademarks of Google LLC.</p></footer>'
def page(path,title,desc,body,image=None,schema=None):
 url=BASE+path; image=image or BASE+'/assets/tripperdeelabs-logo.png'
 tags=f'<title>{E(title)} — TripperDeeLabs</title><meta name="description" content="{E(desc)}"><link rel="canonical" href="{url}">'
 for prop,val in [('og:type','website'),('og:title',title),('og:description',desc),('og:url',url),('og:image',image),('og:image:alt',title)]:tags+=f'<meta property="{prop}" content="{E(val)}">'
 if '/social.png' in image:tags+='<meta property="og:image:width" content="1200"><meta property="og:image:height" content="630">'
 for name,val in [('twitter:card','summary_large_image'),('twitter:title',title),('twitter:description',desc),('twitter:image',image),('twitter:image:alt',title)]:tags+=f'<meta name="{name}" content="{E(val)}">'
 if schema:tags+='<script type="application/ld+json">'+json.dumps(schema).replace('<','\\u003c')+'</script>'
 doc='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'+tags+'<link rel="icon" href="/favicon.svg"><link rel="stylesheet" href="/styles.css"><link rel="stylesheet" href="/catalog.css"><script defer src="/cookie-consent.js"></script></head><body>'+HEADER+'<main class="wrap">'+body+'</main>'+FOOTER+'</body></html>'
 out=ROOT/path.strip('/')/'index.html';out.parent.mkdir(exist_ok=True,parents=True);out.write_text(doc+'\n')
def badge(a):return f'<a class="play-link" href="{E(a["play"])}"><img class="play-badge" src="/assets/google-play-badge.png" width="194" height="75" alt="Get {E(a["name"])} on Google Play"></a>'
def card(a):return f'<article class="app-card"><a href="/{a["slug"]}/"><img class="app-icon" src="/assets/apps/{a["slug"]}/icon.png" width="96" height="96" alt="" loading="lazy"><h3>{E(a["name"])}</h3></a><p>{E(COPY[a["slug"]][1].split(". ")[0])}.</p>'+badge(a)+'</article>'
def social(a,title):
 p=ROOT/'assets/apps'/a['slug'];p.mkdir(parents=True,exist_ok=True);icon=base64.b64encode(((p/'icon.png') if (p/'icon.png').exists() else ROOT/'assets/tripperdeelabs-logo.png').read_bytes()).decode()
 lines=textwrap.wrap(title,31)
 text=''.join(f'<tspan x="390" y="{210+i*58}">{E(line)}</tspan>' for i,line in enumerate(lines))
 svg=f'<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="1200" height="630"><rect width="1200" height="630" fill="#0b1827"/><rect x="48" y="48" width="1104" height="534" rx="28" fill="#142a3a"/><image x="90" y="180" width="240" height="240" xlink:href="data:image/png;base64,{icon}"/><text fill="#f5f3e9" font-family="DejaVu Sans" font-size="44" font-weight="bold">{text}</text><text x="390" y="480" fill="#8ed8c0" font-family="DejaVu Sans" font-size="26">{E(a["os"])} · TripperDeeLabs</text><text x="90" y="550" fill="#bdcbd3" font-family="DejaVu Sans" font-size="22">tripperdeelabs.com/{a["slug"]}/</text></svg>'
 (p/'social.svg').write_text(svg);cairosvg.svg2png(bytestring=svg.encode(),write_to=str(p/'social.png'))
for a in apps:
 slug=a['slug'];title,p1,p2,features=COPY[slug];social(a,title)
 desc=p1
 schema={'@context':'https://schema.org','@type':'SoftwareApplication','name':a['name'],'operatingSystem':a['os'],'applicationCategory':a['category'],'offers':{'@type':'Offer','price':a['price'],'priceCurrency':a['currency'],'url':a['play']},'url':BASE+'/'+slug+'/','image':BASE+'/assets/apps/'+slug+'/social.png','author':{'@type':'Organization','name':'TripperDeeLabs','url':BASE+'/'}}
 price='Free' if float(a['price'])==0 else '$'+a['price']+' USD'
 body=f'<section class="catalog-hero"><img class="app-icon" src="/assets/apps/{slug}/icon.png" width="112" height="112" alt=""><p class="eyebrow">{E(a["os"])}</p><h1>{E(a["name"])}</h1><p class="lead">{E(title)}</p><p>{E(p1)}</p><p>{E(p2)}</p>'+badge(a)+f'<p class="price">{price} on the US Play listing · Checked October 23, 2026. Prices and availability may vary by region.</p></section><section><h2>Features</h2><ul>'+''.join('<li>'+E(f)+'</li>' for f in features)+'</ul></section><section><h2>From the Google Play listing</h2><div class="screenshots">'
 body+=''.join(f'<a href="/assets/apps/{slug}/screenshot-{i+1}.png"><img src="/assets/apps/{slug}/screenshot-{i+1}.png" alt="{E(a["name"])} — Google Play screenshot {i+1}" loading="lazy"></a>' for i in range(len(a['screenshotSources'])))+'</div></section>'
 body+=f'<p><a href="{a["privacy"]}">App privacy policy</a> · <a href="/feedback/?product={slug}">Support</a></p>'
 if slug=='kenai-fishing-report':body+='<p><a href="/kenai-report-data/">Get the Kenai Report Data companion</a></p>'
 page('/'+slug+'/',title,desc,body,BASE+'/assets/apps/'+slug+'/social.png',schema)
groups=[('Phone games',[a for a in apps if a['category']=='GameApplication']),('Phone apps',[a for a in apps if a['os']=='Android' and a['category']!='GameApplication']),('Wear OS watch faces',[a for a in apps if a['os']=='Wear OS' and a['slug']!='kenai-report-data']),('Wear OS companion apps',[a for a in apps if a['slug']=='kenai-report-data'])]
body='<section class="catalog-hero"><p class="eyebrow">Independent Android development</p><h1>Apps for everyday tasks.<br>Games for a little downtime.</h1><p class="lead">Explore TripperDeeLabs games, phone utilities and Wear OS watch faces.</p><a href="#apps">Browse the apps ↓</a></section><div id="apps">'
for name,items in groups:body+='<section><h2>'+name+'</h2><div class="catalog-grid">'+''.join(card(a) for a in items)+'</div></section>'
body+='</div><section><h2>Other projects</h2><p><a href="/alaska-gold-run/">Alaska Gold Run</a> · <a href="/moments/">Moments</a></p></section><section id="about"><h2>About TripperDeeLabs</h2><p>I’m the independent developer behind TripperDeeLabs. I make Android games, practical phone apps and Wear OS watch faces, with projects ranging from Alaska fish reports to retro arcade games.</p><p>For questions or feedback, visit the <a href="/feedback/">feedback page</a>.</p></section>'
page('/','Android Apps, Games and Wear OS Watch Faces','Explore TripperDeeLabs Android games, useful phone apps and Wear OS watch faces, with screenshots, Google Play links and privacy information.',body)
faces=groups[2][1]
page('/garmin/','Wear OS Watch Faces','Explore TripperDeeLabs watch faces for Wear OS, including Dive Watch, Summit Line, Amelia Navigator, Kenai Fishing Report and Launch Vector.','<section class="catalog-hero"><h1>Wear OS watch faces</h1><p>These current Google Play releases are for compatible Wear OS watches. They do not run on Garmin watches.</p></section><div class="catalog-grid">'+''.join(card(a) for a in faces)+'</div><p><a href="/kenai-report-data/">Kenai Report Data companion app</a></p>')
# Unreleased pages make no purchase, pricing or store-screenshot claims.
for slug,name,desc,features in [('alaska-gold-run','Alaska Gold Run','An Alaska-themed Android runner in development. Change lanes, jump and slide through the course.',['Three-lane running','Swipe movement controls','Alaska-themed environments']),('moments','Moments','A photo watch face project for Wear OS. Its public Google Play listing could not be verified.',['Photo watch face concept','Wear OS project','Privacy information available'])]:
 social({'slug':slug,'os':'Android' if slug=='alaska-gold-run' else 'Wear OS'},name)
 page('/'+slug+'/',name+' for '+('Android' if slug=='alaska-gold-run' else 'Wear OS'),desc,f'<section class="catalog-hero"><h1>{name}</h1><p>{desc}</p><p>Not currently verified as available on Google Play. Store screenshots, pricing and a download link will be added when the public listing is available.</p><h2>Project overview</h2><ul>'+''.join('<li>'+f+'</li>' for f in features)+f'</ul><p><a href="/{slug}/privacy/">Privacy policy</a></p></section>',BASE+'/assets/apps/'+slug+'/social.png')
# Preserve existing policy/support text, adding any missing canonical URLs.
for p in ROOT.rglob('*.html'):
 if '.git' in p.parts:continue
 s=p.read_text();rel=p.relative_to(ROOT).as_posix();url=BASE+'/'+(rel[:-10] if rel.endswith('index.html') else rel)
 if 'rel="canonical"' not in s:s=s.replace('</head>',f'<link rel="canonical" href="{url}"></head>');p.write_text(s)
urls=[]
for p in sorted(ROOT.rglob('index.html')):
 rel=p.relative_to(ROOT).as_posix()
 if rel.startswith(('drafts/','.git/')):continue
 urls.append(BASE+'/'+rel[:-10])
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join('  <url><loc>'+u+'</loc></url>\n' for u in urls)+'</urlset>\n')
print(f'Built {len(apps)} verified app pages, 2 unreleased pages, home, watch gallery and sitemap ({len(urls)} URLs).')
